	@Inject
	public ExpressionLanguageGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pExpressionRule = new ExpressionRuleElements();
		this.pOrExpressionRule = new OrExpressionRuleElements();
		this.pXorExpressionRule = new XorExpressionRuleElements();
		this.pAndExpressionRule = new AndExpressionRuleElements();
		this.pNotExpressionRule = new NotExpressionRuleElements();
		this.pComparisonExpressionRule = new ComparisonExpressionRuleElements();
		this.pPartialComparisonExpressionRule = new PartialComparisonExpressionRuleElements();
		this.eComparisonOperatorRule = new ComparisonOperatorRuleElements();
		this.pAddOrSubtractExpressionRule = new AddOrSubtractExpressionRuleElements();
		this.eAddOrSubtractOperatorRule = new AddOrSubtractOperatorRuleElements();
		this.pMultiplyDivideModuloExpressionRule = new MultiplyDivideModuloExpressionRuleElements();
		this.eMultiplyDivideModuloOperatorRule = new MultiplyDivideModuloOperatorRuleElements();
		this.pPowerOfExpressionRule = new PowerOfExpressionRuleElements();
		this.pUnaryAddOrSubtractExpressionRule = new UnaryAddOrSubtractExpressionRuleElements();
		this.pLiteralOrReferenceRule = new LiteralOrReferenceRuleElements();
		this.pParanthesesRule = new ParanthesesRuleElements();
		this.pCallRule = new CallRuleElements();
		this.pFunctionNameRule = new FunctionNameRuleElements();
		this.pValueReferenceRule = new ValueReferenceRuleElements();
		this.pLiteralRule = new LiteralRuleElements();
		this.pNumberLiteralRule = new NumberLiteralRuleElements();
		this.pDoubleLiteralRule = new DoubleLiteralRuleElements();
		this.pIntegerLiteralRule = new IntegerLiteralRuleElements();
		this.pStringLiteralRule = new StringLiteralRuleElements();
		this.eFactorRule = new FactorRuleElements();
		this.pBooleanLiteralRule = new BooleanLiteralRuleElements();
		this.pStringOrId = new StringOrIdElements();
		this.pDOUBLE = new DOUBLEElements();
		this.tSTRING = (TerminalRule) GrammarUtil.findRuleForName(getGrammar(), "de.evoal.languages.model.el.dsl.ExpressionLanguage.STRING");
		this.tQUOTED_ID = (TerminalRule) GrammarUtil.findRuleForName(getGrammar(), "de.evoal.languages.model.el.dsl.ExpressionLanguage.QUOTED_ID");
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("de.evoal.languages.model.el.dsl.ExpressionLanguage".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
